# Social golfers 9-3-6 using AG(3,3) affine geometry
# 27 points = (Z/3)^3, lines are parallel classes by direction
from itertools import product

points = [(a,b,c) for a in range(3) for b in range(3) for c in range(3)]
idx = {p:i for i,p in enumerate(points)}

# Find all directions (nonzero vectors mod scalar). In Z/3, scalars are {1,2}, 2v = -v.
# So directions = nonzero vectors with first nonzero coordinate = 1.
directions = []
for v in product(range(3), repeat=3):
    if v == (0,0,0): continue
    # normalize: first nonzero coord should be 1
    for x in v:
        if x != 0:
            if x == 1:
                directions.append(v)
            break
print(len(directions), directions)

def add(a, v):
    return tuple((a[i]+v[i])%3 for i in range(3))

def mul(v, k):
    return tuple((v[i]*k)%3 for i in range(3))

# For each direction, parallel class = partition into lines {a, a+v, a+2v}
weeks = []
for d in directions[:6]:
    seen = set()
    groups = []
    for p in points:
        if p in seen: continue
        line = [p, add(p,d), add(p,mul(d,2))]
        for q in line: seen.add(q)
        groups.append(line)
    weeks.append(groups)

# Build assignment
sol = [0]*162
for w, groups in enumerate(weeks):
    for g, line in enumerate(groups):
        for p in line:
            sol[w*27 + idx[p]] = g

# Verify
from collections import defaultdict
pair_week = defaultdict(list)
for w in range(6):
    # check partition
    seen = set()
    group_members = defaultdict(list)
    for p in range(27):
        group_members[sol[w*27+p]].append(p)
    assert len(group_members) == 9
    for g, m in group_members.items():
        assert len(m) == 3
        for i in range(3):
            for j in range(i+1,3):
                pair = (m[i],m[j])
                pair_week[pair].append(w)

for pair, ws in pair_week.items():
    assert len(ws) == 1, (pair, ws)

print("OK")
print(sol)
